/* 辅助函数：更新声光报警状态和图标 */
static void Update_Alarm_Status_And_Icons(lv_obj_t * obj)
{
    bool th_zero = (sys_cfg.th_rh_rate == 0.0f && sys_cfg.th_rl_rate == 0.0f);
    bool volume_zero = (sys_cfg.alarm_volume == 0);
    
    /* 1. 更新声报警图标（与光报警一致，尊重 sys_cfg.alarm_sound） */
    if(th_zero || volume_zero || !sys_cfg.alarm_sound)
    {
        _ui_flag_modify(ui_alarm_on, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        _ui_flag_modify(ui_alarm_off, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
    }
    else
    {
        _ui_flag_modify(ui_alarm_on, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
        _ui_flag_modify(ui_alarm_off, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
    }
    
    /* 2. 更新光报警图标和状态 */
    if(th_zero)
    {
        /* 阈值为 0，关闭光报警（即使音量不为 0） */
        _ui_flag_modify(ui_led_on, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        _ui_flag_modify(ui_led_off, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
        sys_cfg.alarm_light = 0;
    }
    else
    {
        /* 阈值不为 0，按照系统参数显示光报警状态 */
        if(sys_cfg.alarm_light)
        {
            _ui_flag_modify(ui_led_off, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
            _ui_flag_modify(ui_led_on, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
        }
        else
        {
            _ui_flag_modify(ui_led_on, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
            _ui_flag_modify(ui_led_off, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
        }
    }
    
    /* 3. 更新光报警状态文本（支持中英文，先同步 current_language 与 sys_cfg.language） */
    language_set_current((Language_t)sys_cfg.language);
    lv_label_set_text(ui_light_alarm_state, sys_cfg.alarm_light ? 
                      language_get_string(LANG_ALARM_STATE_ON) : 
                      language_get_string(LANG_ALARM_STATE_OFF));
    
    /* 4. 根据阈值是否为 0，修改光报警按钮和蜂鸣器音量按钮的文字颜色 */
    if(th_zero)
    {
        /* 阈值为 0，设置标签文字颜色为灰色 (RGB: 999999 = 0x999999) */
        lv_obj_set_style_text_color(ui_Label11, lv_color_hex(0x999999), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(ui_Label21, lv_color_hex(0x999999), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(ui_light_alarm_state, lv_color_hex(0x999999), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(ui_alarm_volume, lv_color_hex(0x999999), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_group_remove_obj(ui_alarm_light_sw);
        lv_group_remove_obj(ui_alarm_beep_sw);
    }
    else
    {
        /* 阈值不为 0，恢复标签文字颜色为默认颜色（0xC6E1FF） */
        lv_obj_set_style_text_color(ui_Label11, lv_color_hex(0xC6E1FF), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(ui_Label21, lv_color_hex(0xC6E1FF), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(ui_light_alarm_state, lv_color_hex(0xC6E1FF), LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_text_color(ui_alarm_volume, lv_color_hex(0xC6E1FF), LV_PART_MAIN | LV_STATE_DEFAULT);
        // lv_group_remove_all_objs(alarm_set_g);
        // lv_group_add_obj(alarm_set_g, ui_Hth_Set_Btn);
        // lv_group_add_obj(alarm_set_g, ui_Lth_Set_Btn);
        lv_group_add_obj(alarm_set_g, ui_alarm_light_sw);
        lv_group_add_obj(alarm_set_g, ui_alarm_beep_sw);
        // if(obj == ui_HthLeft3)
        //     lv_group_focus_obj(ui_Hth_Set_Btn);
        // else
        //     lv_group_focus_obj(ui_Lth_Set_Btn);
    }
    
    // printf("[报警同步] 阈值=%s, 音量=%d%%, 声报警=%d, 光报警=%d\r\n",
    //         th_zero ? "0" : "非 0", (int)sys_cfg.alarm_volume,
    //         (int)sys_cfg.alarm_sound, (int)sys_cfg.alarm_light);
}


