void LightAlarmSwitchOperation(lv_event_t * e)
{
	// Your code here
    const char *alarm_light_state;
    
    alarm_light_state = lv_label_get_text(ui_light_alarm_state);
    
    // 判断当前状态是开还是关（支持中英文）
    bool is_on = (strcmp(alarm_light_state, language_get_string(LANG_ALARM_STATE_ON)) == 0);
    
    if(is_on)
    {
        // 当前是开启状态，切换到关闭
        _ui_flag_modify(ui_led_on, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        _ui_flag_modify(ui_led_off, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
        lv_label_set_text(ui_light_alarm_state, language_get_string(LANG_ALARM_STATE_OFF));
        sys_cfg.alarm_light = 0;
    }
    else
    {
        /* 检查阈值是否都为 0，如果是则不允许开启光报警 */
        bool th_zero = (sys_cfg.th_rh_rate == 0.0f && sys_cfg.th_rl_rate == 0.0f);
        if(th_zero)
        {
            /* 阈值为 0，保持关闭状态 */
            _ui_flag_modify(ui_led_on, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
            _ui_flag_modify(ui_led_off, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
            lv_label_set_text(ui_light_alarm_state, language_get_string(LANG_ALARM_STATE_OFF));
            sys_cfg.alarm_light = 0;
            printf("[LVGL] 阈值为 0，无法开启光报警\r\n");
        }
        else
        {
            /* 阈值不为 0，允许开启 */
            _ui_flag_modify(ui_led_off, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
            _ui_flag_modify(ui_led_on, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
            lv_label_set_text(ui_light_alarm_state, language_get_string(LANG_ALARM_STATE_ON));
            sys_cfg.alarm_light = 1;
        }
    }
    
    if (DeviceConfig_WriteFromSysCfg() != 0)
        printf("[LVGL] 写入光报警开关到 flash %s 失败\r\n", DEVICE_CFG_STORAGE_LABEL);
    else
        printf("[LVGL] 已更新光报警开关：%d 并写入 flash %s\r\n", 
               (int)sys_cfg.alarm_light, DEVICE_CFG_STORAGE_LABEL);
    /* 同步到协议寄存器：仅更新控制位 */
    Net_Config_Sync_To_Registers(CFG_IDX_DEVICE_ADDR);
}

