void ExitHthSetOperation(lv_event_t * e)
{
	// Your code here
    char change_val[16] = {0};
    char L3[2] = {0}, L2[2] = {0}, L1[2] = {0}, R1[2] = {0}, R2[2] = {0}, Unit[8] = {0};

    lv_roller_get_selected_str(ui_HthLeft3, L3, 2);
    lv_roller_get_selected_str(ui_HthLeft2, L2, 2);
    lv_roller_get_selected_str(ui_HthLeft1, L1, 2);
    lv_roller_get_selected_str(ui_HthRight1, R1, 2);
    lv_roller_get_selected_str(ui_HthRight2, R2, 2);
    lv_roller_get_selected_str(ui_HthUnit, Unit, sizeof(Unit));
    strcat(change_val, (L3[0] == '0') ? "" : L3);
    strcat(change_val, (L3[0] == '0') ? ((L2[0] == '0') ? "" : L2) : L2);
    strcat(change_val, L1);
    strcat(change_val, ".");
    strcat(change_val, R1);
    strcat(change_val, R2);
    lv_label_set_text_fmt(ui_high_threshold, "%s %s", change_val, Unit);
    
    // 解析并保存到 sys_cfg
    float hth_val = atof(change_val);
    if(!strcmp(Unit, "mSv/h"))
        sys_cfg.th_rh_rate = hth_val * 1000.0f;  // 转换为 uSv/h
    else
        sys_cfg.th_rh_rate = hth_val;
    
    // 判断阈值是否都为 0，如果是则关闭声光报警
    if(!sys_cfg.th_rh_rate && !sys_cfg.th_rl_rate)
    {
        sys_cfg.alarm_sound = 0;
        sys_cfg.alarm_light = 0;
    }
    
    // 写入 Flash
    if (DeviceConfig_WriteFromSysCfg() != 0)
        printf("[LVGL] 写入高位阈值到 flash %s 失败\r\n", DEVICE_CFG_STORAGE_LABEL);
    else
        printf("[LVGL] 已更新高位阈值：%.2f uSv/h 并写入 flash %s\r\n", 
                (double)sys_cfg.th_rh_rate, DEVICE_CFG_STORAGE_LABEL);
    
    /* 同步到协议寄存器：更新辐射剂量率阈值、报警使能、控制位 */
    Net_Config_Sync_To_Registers(CFG_IDX_RATE);
    Net_Config_Sync_To_Registers(CFG_IDX_ALARM_EN);
    Net_Config_Sync_To_Registers(CFG_IDX_DEVICE_ADDR);
    
    /* 更新 UI 界面的声光报警图标和状态 */
    Update_Alarm_Status_And_Icons(ui_HthLeft3);
    
    lv_indev_set_group(indev_keypad, alarm_set_g);
    lv_group_set_default(alarm_set_g);
    _ui_flag_modify(ui_Panel_high_th_set, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
}

