void ExitDatetimeSetOperation(lv_event_t * e)
{
	// Your code here
    lv_group_t *def_g;
    char year[3] = {0}, month[3] = {0}, day[3] = {0}, hour[3] = {0}, minute[3] = {0};
    char datetime_buf[24];

    lv_roller_get_selected_str(ui_Year, year, 3);
    lv_roller_get_selected_str(ui_month, month, 3);
    lv_roller_get_selected_str(ui_day, day, 3);
    lv_roller_get_selected_str(ui_hour, hour, 3);
    lv_roller_get_selected_str(ui_minute, minute, 3);

    // 更新 env_data
    env_data.dt.year = atoi(year);  // 转换为完整年份（2000-2099）
    env_data.dt.month = atoi(month);
    env_data.dt.day = atoi(day);
    env_data.dt.hour = atoi(hour);
    env_data.dt.minute = atoi(minute);
    env_data.dt.second = 0;
    
    // 同步到 PCF8563
    pcf8563_set_cur_time(&env_data.dt);
    
    // 更新界面显示
    sprintf(datetime_buf, "20%02d/%02d/%02d  %02d:%02d", 
            env_data.dt.year, env_data.dt.month, env_data.dt.day,
            env_data.dt.hour, env_data.dt.minute);
    lv_label_set_text(ui_date, datetime_buf);
    
    // printf("[时间设置] 已更新：%s\r\n", datetime_buf);

    def_g = lv_group_get_default();
    lv_group_remove_all_objs(def_g);
    lv_indev_set_group(indev_keypad, menu_g);
    lv_group_set_default(menu_g);
}

